CREATE TABLE users(id SERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(320) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'user',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE ideas(id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(200) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX ix_ideas_user_id ON ideas(user_id);
CREATE TABLE idea_versions(id SERIAL PRIMARY KEY,idea_id INTEGER NOT NULL REFERENCES ideas(id) ON DELETE CASCADE,version_number INTEGER NOT NULL,problem TEXT NOT NULL,solution TEXT NOT NULL,target_users TEXT NOT NULL,features JSONB NOT NULL,impact TEXT NOT NULL,technology_preference TEXT,team_size INTEGER NOT NULL,team_skill_level VARCHAR(30) NOT NULL,hackathon_duration_hours INTEGER NOT NULL,prototype TEXT,constraints TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(idea_id,version_number)); CREATE INDEX ix_versions_idea ON idea_versions(idea_id);
CREATE TABLE evaluations(id SERIAL PRIMARY KEY,idea_version_id INTEGER NOT NULL REFERENCES idea_versions(id) ON DELETE CASCADE,idea_quality_score DOUBLE PRECISION NOT NULL,build_feasibility_score DOUBLE PRECISION NOT NULL,hackathon_readiness_score DOUBLE PRECISION NOT NULL,analysis_json JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX ix_eval_version ON evaluations(idea_version_id);
CREATE TABLE hackathons(id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(200) NOT NULL,rules_text TEXT NOT NULL,extracted_rules_json JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX ix_hackathons_user ON hackathons(user_id);
